// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;

    function setUp() public { c = new Roulette(); }

    function testFuzz_property(address actor, uint256 targetBlock) public {
        vm.assume(actor != address(0));
        targetBlock = bound(targetBlock, block.number + 1, block.number + 1000);

        vm.deal(actor, 20 ether);

        vm.roll(targetBlock);
        vm.warp(block.timestamp + 1);

        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}('');

        if (ok) {
            if (block.number % 15 == 0) {
                assertTrue(address(c).balance == 0);
            } else {
                assertTrue(address(c).balance >= 0);
            }
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}
